def next_greater_element(nums1, nums2):
    nge, stack = {}, []
    for x in reversed(nums2):
        while stack and stack[-1] <= x:
            stack.pop()
        if stack:
            nge[x] = stack[-1]
        stack.append(x)
    return [nge.get(x, -1) for x in nums1]

