#include <bits/stdc++.h>
using namespace std;

vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
    unordered_map<int, int> nge;
    stack<int> st;
    for (int i = (int)nums2.size() - 1; i >= 0; --i) {
        while (!st.empty() && st.top() <= nums2[i]) st.pop();
        if (!st.empty()) nge[nums2[i]] = st.top();
        st.push(nums2[i]);
    }
    vector<int> ans;
    ans.reserve(nums1.size());
    for (int x : nums1) {
        auto it = nge.find(x);
        ans.push_back(it == nge.end() ? -1 : it->second);
    }
    return ans;
}

